const setMemoryControl = async (
  patch: Partial<{
    injectionEnabled: boolean;
    autoWriteEnabled: boolean;
    autoExtract: "off" | "auto" | "confirm";
  }>,
) => {
  if (configBusy) return;
  // 总闸关闭时强制把抽取档位拨回 off，避免后端静默丢弃产生「以为开了实际没跑」的错觉
  const sanitizedPatch: typeof patch = config.memoryControl.autoWriteEnabled
    ? patch
    : { ...patch, autoExtract: "off" };
  const next = {
    ...config,
    memoryControl: { ...config.memoryControl, ...sanitizedPatch },
  };
  setConfig(next);
  await saveConfig(next);
};

