/// 按 id 集合删除，返回删到的条数
fn pending_delete(conn: &rusqlite::Connection, ids: &[i64]) -> Result<usize, String> {
    ensure_pending_table(conn)?;
    let mut n = 0;
    for id in ids {
        n += conn
            .execute("DELETE FROM mem_pending WHERE id = ?1", [id])
            .map_err(|e| e.to_string())?;
    }
    Ok(n)
}

